CodeChunks.CodeChunk:
// Quest68229, Ruby Sea: serial walking/jump handoffs keep the mesh out of the
// gaps. October22 floor survey supplies these takeoffs and landing elevations.
// LL remains unchanged; its 2D endpoint test is supplemented by stable height.
// Water recovery belongs to the normal GetTo above, never direct uphill input.
if (WorldManager.ZoneId != 613 || !QuestLogManager.HasQuest(68229) || Core.Me.Y <= -55 || Core.Me.IsDead || Core.Me.InCombat) return;
var savedMount = ff14bot.Settings.CharacterSettings.Instance.UseMount;
ff14bot.Settings.CharacterSettings.Instance.UseMount = false;
// The approach's service path can still stop input after its arrival. Remove
// that owner for the entire authored descent, including inter-jump walking.
var previous = ff14bot.Navigation.Navigator.NavigationProvider;
var noPath = new ff14bot.Navigation.NullProvider();
ff14bot.Navigation.Navigator.Clear();
ff14bot.Navigation.Navigator.NavigationProvider = noPath;
// Last five grounded approach samples measure current speed, including active buffs.
var approachSpeeds = new System.Collections.Generic.List<float>();
Func<Clio.Utilities.Vector3, float, System.Threading.Tasks.Task<bool>> walk = async (point, tolerance) =>
{
    var deadline = DateTime.UtcNow.AddSeconds(12);
    try
    {
        while (Core.Me.Location.Distance(point) > tolerance)
        {
            if (QuestLogManager.InCutscene || ff14bot.RemoteWindows.Talk.DialogOpen || DateTime.UtcNow > deadline || Core.Me.IsDead || Core.Me.InCombat || WorldManager.ZoneId != 613 || Core.Me.Y < point.Y - 4)
            { ff14bot.Helpers.Logging.Write("[SwordStone] Walk interrupted at="+Core.Me.Location+" goal="+point); return false; }
            ff14bot.Navigation.Navigator.PlayerMover.MoveTowards(point);
            if (MovementManager.Speed > 1f)
            {
                approachSpeeds.Add(MovementManager.Speed);
                if (approachSpeeds.Count > 5) approachSpeeds.RemoveAt(0);
            }
            await Coroutine.Yield();
        }
        return true;
    }
    finally { ff14bot.Navigation.Navigator.PlayerMover.MoveStop(); MovementManager.MoveStop(); }
};
// LL owns the actual forward/jump sequence. This wrapper measures a grounded
// approach and relocates that sequence so faster travel starts farther back.
// Nothing pulses a second mover while JumpNav.Jump is awaiting its landing.
Func<Clio.Utilities.Vector3, Clio.Utilities.Vector3, System.Threading.Tasks.Task<bool>> jump = async (start, end) =>
{
    var route = new LlamaLibrary.Helpers.JumpNav(start, end);
    if (route.IsAtEnd() && Math.Abs(Core.Me.Y - end.Y) < 1.5f) return true;
    var direction = end - start;
    direction.Y = 0;
    direction /= direction.Distance(Clio.Utilities.Vector3.Zero);
    // Collision-only rays ignore invisible event boundaries. A missing floor
    // refuses the launch; water can never masquerade as the starting shelf.
    Func<Clio.Utilities.Vector3, Clio.Utilities.Vector3?> floor = point =>
    {
        Clio.Utilities.Vector3 hit;
        return WorldManager.AdvancedRaycast(point + new Clio.Utilities.Vector3(0, 3, 0), point - new Clio.Utilities.Vector3(0, 4, 0),
            ff14bot.Enums.RaycastFlags.PassthruBoundaries, ff14bot.Enums.RaycastFlags.PassthruBoundaries, out hit) && hit.Y > -50
            ? (Clio.Utilities.Vector3?)hit : null;
    };
    //2.5y of supported approach lets acceleration settle before the median of five samples.
    var staging = floor(start - direction * 2.5f);
    if (!staging.HasValue || !await walk(staging.Value, .2f)) return false;
    approachSpeeds.Clear();
    if (!await walk(start, .15f) || approachSpeeds.Count < 3) return false;
    var samples = approachSpeeds.OrderBy(v => v).ToArray();
    float speed = samples[samples.Length / 2];
    // Normal6y/s is the tested geometric anchor, not an assumed runtime speed.
    // Heavy/walking and out-of-range motion wait for a later safe retry rather
    // than deliberately jumping a gap that cannot be reached at that speed.
    //5.8 allows base6 measurement noise;8.1 includes verified7.8 Sprint with a small reserve.
    //A0.8 spread among the last five samples signals acceleration/buff transition.
    if (speed < 5.8f || speed > 8.1f || samples.Last() - samples.First() > .8f)
    {
        ff14bot.Helpers.Logging.Write("[SwordStone] Unstable/impaired approach speed=" + speed + "; launch deferred.");
        return false;
    }
    // The captured6/7.8y/s descents change horizontal reach by about1.1y per
    // extra y/s. Adjust launch POSITION by that measured response; LL still owns
    // flight duration. A ballistic height extrapolation overcompensated on the
    // sloped takeoff and hit the landing's front wall during the Sprint test.
    // Wait if a known speed buff would end during facing/run-up/flight.
    if (Core.Me.Auras.Any(a => (a.Id == 50 || a.Id == 1199) && a.TimespanLeft.TotalSeconds < 6))
    {
        ff14bot.Helpers.Logging.Write("[SwordStone] Speed buff expiring; launch deferred until speed settles.");
        return false;
    }
    var adjusted = floor(start - direction * ((speed - 6f) * 1.1f));
    if (!adjusted.HasValue) return false;
    var launch = adjusted.Value;
    // Verify the entire offset from the surveyed takeoff and LL's run-up strip.
    //0.22*speed covers acceleration,200ms run-up and a small input reserve;
    //2y permits this quest's measured descending rock but rejects its cliff.
    for (int i = 0; i <= 8; ++i)
    {
        var p = start + (launch - start) * (i / 8f);
        if (!floor(p).HasValue) return false;
        var support = floor(launch + direction * (speed * .22f * i / 8f));
        if (!support.HasValue || support.Value.Y < launch.Y - 2f) return false;
    }
    if (!await walk(launch, .15f)) return false;
    // LL waits for any heading change, not alignment; finish facing before its
    // movement handoff. No fixed heading or character-specific speed is stored.
    double bearing = Math.Atan2(end.X - Core.Me.X, end.Z - Core.Me.Z);
    Core.Me.Face(end);
    if (!await Coroutine.Wait(1200, () => Math.Abs(Math.Atan2(Math.Sin(Core.Me.Heading - bearing), Math.Cos(Core.Me.Heading - bearing))) < .025)) return false;
    ff14bot.Navigation.Navigator.Clear();
    route = new LlamaLibrary.Helpers.JumpNav(launch, end);
    ff14bot.Helpers.Logging.Write("[SwordStone] Jump speed=" + speed + " from=" + Core.Me.Location + " to=" + end);
    bool result;
    try { result = await route.Jump(); }
    finally { MovementManager.MoveStop(); }
    var foot = Core.Me.Location;
    await Coroutine.Sleep(200);
    result = result && route.IsAtEnd() && Math.Abs(Core.Me.Y - end.Y) < 1.5f &&
        Math.Abs(Core.Me.Y - foot.Y) < .08f && !LlamaLibrary.Helpers.GeneralFunctions.IsJumping;
    ff14bot.Helpers.Logging.Write("[SwordStone] Landing=" + result + " at=" + Core.Me.Location + " step=" + QuestLogManager.GetQuestStep(68229));
    return result;
};


try
{
    if (Core.Me.IsMounted) await ff14bot.Behavior.CommonTasks.StopAndDismount();
    // Approach measurement includes current buffs; do not wait for a specific class aura.
    // A failed step3 attempt can retain its journal step. At the upper slope,
    // replay the first crossing instead of aiming at the second shelf below it.
    if (QuestLogManager.GetQuestStep(68229) == 2 || (QuestLogManager.GetQuestStep(68229) == 3 && Core.Me.Y > -25))
    {
        // The first slope is continuous rock, so walk its two bends before the gap.
        if (Core.Me.Y > -10)
        {
            if (!await walk(new Clio.Utilities.Vector3(611.0259f, -1.795426f, -90.84206f), .4f)) return;
            if (!await walk(new Clio.Utilities.Vector3(612.9421f, -1.754529f, -92.88273f), .2f)) return;
        }
        if (!await jump(new Clio.Utilities.Vector3(617.265f, -18.794312f, -115.272f), new Clio.Utilities.Vector3(619.56024f, -29.353806f, -125.00472f))) return;
        // This landing triggers the sword event and temporarily locks movement.
        // Return to OrderBot for its dialogue/event scheduling before step3;
        // retaining the RunCode coroutine here stalls the scripted handoff.
        return;
    }
    if (QuestLogManager.GetQuestStep(68229) == 3)
    {
        // These separated shelf heights also reconstruct progress after a
        // manual stop; never walk back toward a higher, already-crossed gap.
        // The second launch also moves0.45y forward: normal-speed capture clipped the near wall.
        if (Core.Me.Y > -33 && !await jump(new Clio.Utilities.Vector3(616.7f, -29.447f, -131.125f), new Clio.Utilities.Vector3(608.9372f, -35.343384f, -134.70822f))) return;
        // Rowan at6y/s undershot the Mira-calibrated takeoff. October22 floor survey and replay verified this later grounded launch.
        if (Core.Me.Y > -40 && !await jump(new Clio.Utilities.Vector3(601.84f, -36.87f, -145f), new Clio.Utilities.Vector3(600f, -43.9f, -154f))) return;
        // Normal-speed touchdown reaches the lip; step onto supported rock to enter the objective trigger.
        if (Core.Me.Y > -48 && Core.Me.Y < -40 && !QuestLogManager.InCutscene && !ff14bot.RemoteWindows.Talk.DialogOpen)
            await walk(new Clio.Utilities.Vector3(600f, -43.9f, -154f), .2f);
        // The third landing completes the challenge. Return for the scripted
        // event before the separate step255 water exit; holding this coroutine
        // through that event delays the dialogue and completion handoff.
        return;
    }
}
finally
{
    MovementManager.MoveStop();
    if (ReferenceEquals(ff14bot.Navigation.Navigator.NavigationProvider, noPath))
        ff14bot.Navigation.Navigator.NavigationProvider = previous;
    ff14bot.Settings.CharacterSettings.Instance.UseMount = savedMount;
    ff14bot.Helpers.Logging.Write("[SwordStone] Traversal released at=" + Core.Me.Location + " step=" + QuestLogManager.GetQuestStep(68229));
}

if (WorldManager.ZoneId != 613 || QuestLogManager.GetQuestStep(68229) != 255 ||
    Core.Me.IsDead || Core.Me.InCombat || QuestLogManager.InCutscene || ff14bot.RemoteWindows.Talk.DialogOpen) return;
var previous = ff14bot.Navigation.Navigator.NavigationProvider;
var noPath = new ff14bot.Navigation.NullProvider();
var savedMount = ff14bot.Settings.CharacterSettings.Instance.UseMount;
ff14bot.Navigation.Navigator.Clear();
ff14bot.Navigation.Navigator.NavigationProvider = noPath;
ff14bot.Settings.CharacterSettings.Instance.UseMount = false;
try
{
    // Retain the authored rock edge and water approach. This owner hands back
    // to GetTo only after releasing direct input; no jump or mesh races it.
    var points = new[] {
        new Clio.Utilities.Vector3(596.343f, -43.55858f, -157.2047f),
        new Clio.Utilities.Vector3(567.4005f, -62.05959f, -145.2847f)
    };
    foreach (var point in points)
    {
        if (point.Y > -55 && Core.Me.Y < -48) continue;
        var deadline = DateTime.UtcNow.AddSeconds(15);
        while (Core.Me.Location.Distance(point) > 1f)
        {
            if (Core.Me.IsDead || Core.Me.InCombat || WorldManager.ZoneId != 613 ||
                QuestLogManager.GetQuestStep(68229) != 255 || DateTime.UtcNow > deadline) return;
            ff14bot.Navigation.Navigator.PlayerMover.MoveTowards(point);
            await Coroutine.Yield();
        }
    }
    ff14bot.Helpers.Logging.Write("[SwordStone] Completed challenge water exit reached=" + Core.Me.Location);
}
finally
{
    ff14bot.Navigation.Navigator.PlayerMover.MoveStop();
    MovementManager.MoveStop();
    if (ReferenceEquals(ff14bot.Navigation.Navigator.NavigationProvider, noPath))
        ff14bot.Navigation.Navigator.NavigationProvider = previous;
    ff14bot.Settings.CharacterSettings.Instance.UseMount = savedMount;
}
